from __future__ import annotations

import click

from .models import Note, generate_id
from .search import search as do_search
import sys
import re
from .storage import get_notes, add_note, delete_note


def _validate_non_empty(ctx, param, value):
    if not value or not value.strip():
        raise click.BadParameter(f"{param.name.capitalize()} cannot be empty.")
    return value


@click.group()
def cli():
    """Simple note‑taking CLI."""
    pass


@cli.command()
@click.option("--title", required=True, help="Note title.", callback=_validate_non_empty)
@click.option("--body", required=True, help="Note body text.", callback=_validate_non_empty)
@click.option(
    "--tags",
    default="",
    help="Comma‑separated list of tags (e.g. 'python,cli').",
)
def add(title: str, body: str, tags: str) -> None:
    """Create a new note."""
    parsed_tags = [t.strip() for t in tags.split(",") if t.strip()] if tags else []
    for tag in parsed_tags:
        if len(tag) > 100:
            click.echo(f"Error: Tag '{tag}' exceeds maximum length of 100 characters.")
            sys.exit(1)
        if not re.match(r'^[a-zA-Z0-9_-]+$', tag):
            click.echo(f"Error: Tag '{tag}' contains invalid characters. Only letters, digits, hyphens, and underscores are allowed.")
            sys.exit(1)
    note = Note(id=generate_id(), title=title, body=body, tags=parsed_tags)
    add_note(note)
    click.echo(f"Added note {note.id}")


@cli.command(name="list")
@click.option(
    "--tags",
    default="",
    help="Comma‑separated list of tags to filter by.",
)
def cmd_list(tags: str) -> None:
    """List all notes."""
    parsed_tags = [t.strip() for t in tags.split(",") if t.strip()] if tags else None
    results = do_search(get_notes(), query="", tags=parsed_tags)
    if not results:
        click.echo("No notes found.")
        return
    for n in results:
        tag_str = ", ".join(n.tags) if n.tags else "(none)"
        click.echo(f"[{n.id}] {n.title}  tags: {tag_str}")


@cli.command()
@click.option("--query", required=True, help="Search query (substring).")
@click.option(
    "--tags",
    default="",
    help="Comma‑separated list of tags to filter by.",
)
def search(query: str, tags: str) -> None:
    """Search notes by query and/or tags."""

    parsed_tags = [t.strip() for t in tags.split(",") if t.strip()] if tags else None
    results = do_search(get_notes(), query=query, tags=parsed_tags)
    if not results:
        click.echo("No matching notes.")
        return
    for n in results:
        tag_str = ", ".join(n.tags) if n.tags else "(none)"
        click.echo(f"[{n.id}] {n.title}  tags: {tag_str}")


@cli.command()
@click.argument("note_id")
def delete(note_id: str) -> None:
    """Delete a note by its id."""
    if delete_note(note_id):
        click.echo(f"Deleted note {note_id}")
    else:
        click.echo(f"Note {note_id} not found.")


def main() -> None:
    cli()

