"""File-based JSON storage for notes."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Dict, List

from .models import Note

DEFAULT_PATH: Path = Path(__file__).resolve().parents[2] / "out.json"
# Backward-compatible alias
STORAGE_PATH: Path = DEFAULT_PATH


def _read_store(path: Path = DEFAULT_PATH) -> Dict[str, Any]:
    """Read the store from *path*.

    Returns ``{"notes": []}`` if the file is missing; raises on invalid JSON.
    """
    if not path.exists():
        return {"notes": []}
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError, UnicodeDecodeError):
        return {"notes": []}
    if not isinstance(raw, dict):
        return {"notes": []}
    notes = raw.get("notes")
    if not isinstance(notes, list):
        return {"notes": []}
    return raw


def _write_store(path: Path, store: Dict[str, Any]) -> None:
    """Write *store* to *path* as JSON."""
    path.write_text(json.dumps(store, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


def get_notes(path: Path = DEFAULT_PATH) -> List[Note]:
    """Return all notes from the store at *path*."""
    raw = _read_store(path)
    return [Note.from_dict(d) for d in raw.get("notes", [])]


def add_note(note: Note, path: Path = DEFAULT_PATH) -> None:
    """Append *note* to the store at *path*."""
    raw = _read_store(path)
    raw.setdefault("notes", []).append(note.to_dict())
    _write_store(path, raw)


def delete_note(note_id: str, path: Path = DEFAULT_PATH) -> bool:
    """Remove the note with *note_id* from the store.

    Returns ``True`` iff a matching note was found and removed.
    """
    raw = _read_store(path)
    notes: List[Dict[str, Any]] = raw.get("notes", [])
    before_len = len(notes)
    notes[:] = [d for d in notes if d.get("id") != note_id]
    raw["notes"] = notes
    if len(notes) < before_len:
        _write_store(path, raw)
        return True
    return False


def clear_all(path: Path = DEFAULT_PATH) -> None:
    """Wipe all notes and write a fresh empty store."""
    _write_store(path, {"notes": []})

