            "title": self.title,
            "body": self.body,
            "pinned": self.pinned,
            "tags": self.tags,
        }

    @classmethod
    def from_dict(cls, d: dict) -> Note:
        return cls(
            id=d["id"],
            title=d["title"],
            body=d["body"],
            pinned=d.get("pinned", False),
            tags=d.get("tags", []),
        )


